import { OperatingSystemName } from '../types';
import { userAgent } from '../user-agent';
import { DeviceSystem } from './device-system';

const isIPadPretendingToBeDesktop = 'ontouchstart' in window && userAgent.os.name === 'Mac OS';
const osName = isIPadPretendingToBeDesktop ? 'iOS' : userAgent.os.name as OperatingSystemName;

export class OperatingSystem extends DeviceSystem<OperatingSystemName> {
    constructor() {
        super(osName, userAgent.os.version);
    }
}